import 'package:ssb_crypto/ssb_crypto.dart';
import 'package:test/test.dart';

/// Official RFC 9180 Appendix A.1.1 (DHKEM(X25519, HKDF-SHA256), HKDF-SHA256,
/// AES-128-GCM, mode_base). Values copied from the RFC, not generated by this
/// code. Our key schedule is fixed at Nk=32, so the 16-byte `key` is not
/// compared; key_schedule_context, base_nonce and exporter_secret do not depend
/// on Nk and prove the secret is derived exactly as RFC 9180 section 5.1 says
/// (psk_id_hash goes into the context; the secret uses the empty default psk).
void main() {
  test('RFC 9180 A.1.1 key schedule: context, base_nonce, exporter_secret', () async {
    final ks = await Hpke.keySchedule(
        hexDecode('fe0e18c9f024ce43799ae393c7e8fe8fce9d218875e8227b0187c04e7d2ea1fc'),
        hexDecode('4f6465206f6e2061204772656369616e2055726e'),
        kemId: 0x0020, kdfId: 0x0001, aeadId: 0x0001);
    expect(hexEncode(ks.context),
        '00725611c9d98c07c03f60095cd32d400d8347d45ed67097bbad50fc56da742d07cb6cffde367bb0565ba28bb02c90744a20f5ef37f30523526106f637abb05449');
    expect(hexEncode(ks.baseNonce), '56d890e5accaaf011cff4b7d');
    expect(hexEncode(ks.exporterSecret),
        '45ff1c2e220db587171952c0592d5f5ebe103f1561a2614e38f2ffd47e99e3f8');
  });
}
